/**
 * 단방향 수치 입력 필드 — label + input
 */
export default function UnitInput({ id, label, value, onChange, unit, placeholder = '0' }) {
  return (
    <div style={{ marginBottom: 16 }}>
      <label
        htmlFor={id}
        style={{
          display: 'block',
          fontSize: 12,
          fontWeight: 500,
          color: 'var(--tx-secondary)',
          marginBottom: 4,
        }}
      >
        {label}{unit && <span style={{ color: 'var(--tx-muted)', marginLeft: 4 }}>({unit})</span>}
      </label>
      <input
        id={id}
        type="number"
        inputMode="numeric"
        value={value}
        onChange={e => onChange(e.target.value)}
        placeholder={placeholder}
        style={{
          background: 'var(--bg-input)',
          border: '1px solid var(--bd-subtle)',
          borderRadius: 6,
          color: 'var(--tx-primary)',
          padding: '6px 10px',
          width: '100%',
          textAlign: 'center',
          fontSize: 15,
          fontWeight: 600,
          transition: 'border-color 0.2s, box-shadow 0.2s',
        }}
        onFocus={e => {
          e.target.style.borderColor = 'var(--ac-main)'
          e.target.style.boxShadow = '0 0 0 3px var(--ac-glow)'
        }}
        onBlur={e => {
          e.target.style.borderColor = 'var(--bd-subtle)'
          e.target.style.boxShadow = 'none'
        }}
      />
    </div>
  )
}
